                let (results, refused, _) =
                    crate::bounded_output::with_limit_usage(usize::MAX, || {
                        reserve_program_skeleton_work(
                            &program,
                            std::iter::once(function),
                            &mut budget,
                        )
                        .unwrap();
                        let mut results = Vec::new();
                        for ty in function
                            .params
                            .iter()
                            .map(|p| &p.ty)
                            .chain(std::iter::once(&function.return_type))
